    I = ( I/iResolution.xy + vec2(12,15) )/16.;                   // choose char coordinates

    float d = textureLod(iChannel0, I, 3.*(.5-.5*cos(iTime)) ).w; // cycles LODs  try .w vs .x

    O = vec4(smoothstep( -1.,1., (d-.5)/fwidth(d)));              // AA thresholds

